<?php
declare(strict_types=1);

// Gestión de tareas y entregas.
// Los docentes publican asignaciones y los estudiantes entregan respuestas y archivos adjuntos.
require __DIR__.'/../includes/auth.php';require_login();require_once __DIR__.'/../config/database.php';require __DIR__.'/../includes/uploads.php';csrf_check();
$me=$_SESSION['user'];$uid=(int)$me['id'];$role=$me['role'];$flash='';
if(!in_array($role,['student','teacher','admin'],true)){http_response_code(403);exit('No tienes acceso a tareas.');}
if($_SERVER['REQUEST_METHOD']==='POST'){
 $action=(string)($_POST['action']??'');
 try{
  if($role==='teacher'&&$action==='assignment_create'){
   $title=trim((string)($_POST['title']??''));$instructions=trim((string)($_POST['instructions']??''));$grade=filter_var($_POST['grade_level']??null,FILTER_VALIDATE_INT);$group=(int)($_POST['group_id']??0);$due=trim((string)($_POST['due_at']??''));$max=(float)($_POST['max_score']??100);
   if(mb_strlen($title)<3||mb_strlen($title)>180||$instructions===''||mb_strlen($instructions)>12000||$max<=0||$max>100000)throw new RuntimeException('Revisa título, instrucciones y puntuación máxima.');
   if($group){$g=$pdo->prepare('SELECT id,grade_level FROM teacher_groups WHERE id=? AND teacher_id=?');$g->execute([$group,$uid]);$groupRow=$g->fetch();if(!$groupRow)throw new RuntimeException('El grupo no pertenece a tu cuenta.');$grade=(int)$groupRow['grade_level'];}
   elseif($grade===false||$grade<5||$grade>11)throw new RuntimeException('Selecciona un grado válido o un grupo propio.');
   $dueAt=null;if($due!==''){$dt=DateTime::createFromFormat('Y-m-d\TH:i',$due);if(!$dt)throw new RuntimeException('La fecha límite no es válida.');$dueAt=$dt->format('Y-m-d H:i:s');}
   $file=store_assignment_upload($_FILES['material']??[]);$pdo->beginTransaction();try{$pdo->prepare('INSERT INTO assignments(teacher_id,title,instructions,subject_id,grade_level,due_at,max_score,status,allow_resubmission) VALUES(?,?,?,?,?,?,?,?,?)')->execute([$uid,$title,$instructions,((int)($_POST['subject_id']??0))?:null,$grade,$dueAt,$max,isset($_POST['publish'])?'published':'draft',isset($_POST['allow_resubmission'])?1:0]);$aid=(int)$pdo->lastInsertId();$pdo->prepare('INSERT INTO assignment_targets(assignment_id,group_id,grade_level) VALUES(?,?,?)')->execute([$aid,$group?:null,$group?null:$grade]);link_assignment_upload($pdo,$aid,null,$uid,$file);audit_event($pdo,$uid,'assignment.created',['assignment_id'=>$aid]);$pdo->commit();$flash='Tarea guardada.'.(isset($_POST['publish'])?' Publicada.':' Quedó como borrador.');}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();if($file)@unlink(private_upload_dir().DIRECTORY_SEPARATOR.$file['storage_name']);throw $e;}
  }elseif($role==='teacher'&&$action==='assignment_status'){$aid=(int)($_POST['assignment_id']??0);$status=(string)($_POST['status']??'');if(!in_array($status,['published','closed'],true))throw new RuntimeException('Estado no válido.');$q=$pdo->prepare('UPDATE assignments SET status=? WHERE id=? AND teacher_id=?');$q->execute([$status,$aid,$uid]);if(!$q->rowCount())throw new RuntimeException('Tarea no encontrada o sin cambios.');audit_event($pdo,$uid,'assignment.status_changed',['assignment_id'=>$aid,'status'=>$status]);$flash='Estado de la tarea actualizado.';
  }elseif($role==='teacher'&&$action==='assignment_edit'){$aid=(int)($_POST['assignment_id']??0);$title=trim((string)($_POST['title']??''));$instructions=trim((string)($_POST['instructions']??''));$q=$pdo->prepare('SELECT id FROM assignments WHERE id=? AND teacher_id=? AND status=\'draft\' AND NOT EXISTS(SELECT 1 FROM assignment_submissions s WHERE s.assignment_id=assignments.id)');$q->execute([$aid,$uid]);if(!$q->fetchColumn()||mb_strlen($title)<3||mb_strlen($title)>180||$instructions===''||mb_strlen($instructions)>12000)throw new RuntimeException('Solo se pueden editar borradores propios sin entregas.');$pdo->prepare('UPDATE assignments SET title=?,instructions=? WHERE id=? AND teacher_id=?')->execute([$title,$instructions,$aid,$uid]);$flash='Borrador actualizado.';
  }elseif($role==='student'&&$action==='assignment_submit'){$aid=(int)($_POST['assignment_id']??0);$text=trim((string)($_POST['response_text']??''));if(mb_strlen($text)>20000)throw new RuntimeException('La respuesta supera 20.000 caracteres.');$a=$pdo->prepare("SELECT a.id,a.due_at,a.status,a.allow_resubmission FROM assignments a WHERE a.id=? AND a.status='published' AND EXISTS(SELECT 1 FROM assignment_targets t WHERE t.assignment_id=a.id AND (t.student_id=? OR (t.grade_level=? AND t.group_id IS NULL) OR (t.group_id IS NOT NULL AND EXISTS(SELECT 1 FROM group_students gs WHERE gs.group_id=t.group_id AND gs.student_id=?))))");$a->execute([$aid,$uid,$me['grade_level']??null,$uid]);$assignment=$a->fetch();if(!$assignment)throw new RuntimeException('No tienes acceso a esa tarea o ya fue cerrada.');$old=$pdo->prepare('SELECT id,status FROM assignment_submissions WHERE assignment_id=? AND student_id=?');$old->execute([$aid,$uid]);$prev=$old->fetch();if($prev&&!((int)$assignment['allow_resubmission']===1&&$prev['status']==='returned'))throw new RuntimeException('Ya tienes un borrador o entrega. Solo puedes reenviar si el docente la devolvió.');$file=store_assignment_upload($_FILES['submission_file']??[]);$draft=$action==='assignment_draft';$status=$draft?'draft':(!empty($assignment['due_at'])&&strtotime($assignment['due_at'])<time()?'late':'submitted');$pdo->beginTransaction();try{if($prev){$sid=(int)$prev['id'];$pdo->prepare('UPDATE assignment_submissions SET response_text=?,status=?,submitted_at=?,score=NULL,feedback=NULL,graded_by=NULL,graded_at=NULL WHERE id=? AND student_id=?')->execute([$text,$status,$draft?null:date('Y-m-d H:i:s'),$sid,$uid]);}else{$pdo->prepare('INSERT INTO assignment_submissions(assignment_id,student_id,response_text,status,submitted_at) VALUES(?,?,?,?,?)')->execute([$aid,$uid,$text,$status,$draft?null:date('Y-m-d H:i:s')]);$sid=(int)$pdo->lastInsertId();}link_assignment_upload($pdo,$aid,$sid,$uid,$file);if(!$draft){$teacherId=$pdo->prepare('SELECT teacher_id FROM assignments WHERE id=?');$teacherId->execute([$aid]);$pdo->prepare('INSERT INTO notifications(user_id,title,body) VALUES(?,?,?)')->execute([$teacherId->fetchColumn(),'Nueva entrega','Un estudiante envió una respuesta a una tarea.']);}audit_event($pdo,$uid,$draft?'assignment.draft_saved':'assignment.submitted',['assignment_id'=>$aid]);$pdo->commit();$flash=$draft?'Borrador guardado.':'Tarea entregada.';}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();if($file)@unlink(private_upload_dir().DIRECTORY_SEPARATOR.$file['storage_name']);throw $e;}
  }elseif($role==='teacher'&&$action==='submission_grade'){$sid=(int)($_POST['submission_id']??0);$score=filter_var($_POST['score']??null,FILTER_VALIDATE_FLOAT);$feedback=trim((string)($_POST['feedback']??''));$state=(string)($_POST['submission_status']??'graded');if($score===false||$score<0||mb_strlen($feedback)>5000||!in_array($state,['graded','returned'],true))throw new RuntimeException('Revisa la nota, el comentario y el estado.');$q=$pdo->prepare('SELECT s.id,s.student_id,a.max_score,a.id assignment_id FROM assignment_submissions s JOIN assignments a ON a.id=s.assignment_id WHERE s.id=? AND a.teacher_id=?');$q->execute([$sid,$uid]);$row=$q->fetch();if(!$row||$score>(float)$row['max_score'])throw new RuntimeException('La entrega no pertenece a tus tareas o supera la nota máxima.');$pdo->prepare('UPDATE assignment_submissions SET score=?,feedback=?,status=?,graded_by=?,graded_at=NOW() WHERE id=?')->execute([$score,$feedback,$state,$uid,$sid]);$pdo->prepare('INSERT INTO notifications(user_id,title,body) VALUES(?,?,?)')->execute([$row['student_id'],$state==='returned'?'Tarea devuelta':'Tarea calificada',$state==='returned'?'Tu docente devolvió la tarea para corregir.':'Tu docente dejó una calificación y retroalimentación.']);audit_event($pdo,$uid,'assignment.graded',['submission_id'=>$sid,'status'=>$state]);$flash=$state==='returned'?'Entrega devuelta para corrección.':'Calificación guardada.';
  }
 }catch(Throwable $e){$flash=$e instanceof RuntimeException?$e->getMessage():'No se pudo guardar la operación. Revisa la migración y el archivo adjunto.';}
}
$subjects=$pdo->query('SELECT id,name FROM subjects ORDER BY name')->fetchAll();$groups=[];if($role==='teacher'){$g=$pdo->prepare('SELECT id,name,grade_level FROM teacher_groups WHERE teacher_id=? ORDER BY name');$g->execute([$uid]);$groups=$g->fetchAll();}
?><!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Tareas · Prossor AI</title><link rel="stylesheet" href="assets/css/app.css"></head><body class="app-body"><main class="main-content"><header class="topbar"><a href="dashboard.php">← Mi espacio</a><b>Tareas</b></header><?php if($flash): ?><div class="notice flash"><?= h($flash) ?></div><?php endif; ?>
<?php if($role==='teacher'): ?><section class="welcome"><div><p class="eyebrow">DOCENTES</p><h1>Gestiona tareas</h1><p class="muted">Asigna por grupo o grado. Las entregas y notas se guardan en el servidor.</p></div></section><section class="panel"><h2>Nueva tarea</h2><form method="post" enctype="multipart/form-data" class="stack"><input type="hidden" name="csrf" value="<?= h(csrf_token()) ?>"><label>Título<input name="title" minlength="3" maxlength="180" required></label><label>Instrucciones<textarea name="instructions" maxlength="12000" required></textarea></label><label>Asignatura (opcional)<select name="subject_id"><option value="0">Sin asignatura</option><?php foreach($subjects as $subject): ?><option value="<?= (int)$subject['id'] ?>"><?= h($subject['name']) ?></option><?php endforeach; ?></select></label><label>Asignar a un grupo (opcional)<select name="group_id"><option value="0">Elegir por grado</option><?php foreach($groups as $g): ?><option value="<?= (int)$g['id'] ?>"><?= h($g['name']) ?> · Grado <?= (int)$g['grade_level'] ?></option><?php endforeach; ?></select></label><label>Grado si no elegiste grupo<select name="grade_level"><option value="">Grado</option><?php for($i=5;$i<=11;$i++): ?><option value="<?= $i ?>"><?= $i ?>°</option><?php endfor; ?></select></label><label>Fecha límite<input type="datetime-local" name="due_at"></label><label>Puntuación máxima<input type="number" name="max_score" min="1" max="100000" step="0.01" value="100" required></label><label>Material adjunto (PDF, imagen, TXT o DOCX; 5 MB)<input type="file" name="material" accept=".pdf,.png,.jpg,.jpeg,.txt,.docx"></label><label><input type="checkbox" name="allow_resubmission" value="1"> Permitir reenvío si devuelvo el trabajo</label><label><input type="checkbox" name="publish" value="1"> Publicar ahora</label><button class="button primary" name="action" value="assignment_create">Guardar tarea</button></form></section><?php $q=$pdo->prepare('SELECT a.*,COUNT(DISTINCT s.id) submissions,COUNT(DISTINCT CASE WHEN s.status=\'graded\' THEN s.id END) graded FROM assignments a LEFT JOIN assignment_submissions s ON s.assignment_id=a.id WHERE a.teacher_id=? GROUP BY a.id ORDER BY a.created_at DESC');$q->execute([$uid]);foreach($q->fetchAll() as $a): ?><section class="panel"><h2><?= h($a['title']) ?> <span class="soft-tag"><?= h($a['status']) ?></span></h2><p><?= h($a['instructions']) ?></p><p class="muted">Entregas: <?= (int)$a['submissions'] ?> · Calificadas: <?= (int)$a['graded'] ?> · Máximo: <?= h((string)$a['max_score']) ?></p><?php if($a['status']!=='closed'): ?><form method="post"><input type="hidden" name="csrf" value="<?= h(csrf_token()) ?>"><input type="hidden" name="assignment_id" value="<?= (int)$a['id'] ?>"><button class="mini-button" name="action" value="assignment_status" formaction="tareas.php">Cerrar tarea</button><input type="hidden" name="status" value="closed"></form><?php endif; ?><?php $s=$pdo->prepare('SELECT s.*,u.name student FROM assignment_submissions s JOIN users u ON u.id=s.student_id WHERE s.assignment_id=? ORDER BY s.submitted_at DESC');$s->execute([$a['id']]);foreach($s->fetchAll() as $row): ?><article class="plan-row"><div><b><?= h($row['student']) ?> · <?= h($row['status']) ?></b><small><?= nl2br(h((string)$row['response_text'])) ?><?= $row['feedback']?'<br>Retroalimentación: '.h($row['feedback']):'' ?></small><?php $f=$pdo->prepare('SELECT id,original_name FROM assignment_files WHERE submission_id=?');$f->execute([$row['id']]);foreach($f->fetchAll() as $file): ?><a href="descargar-adjunto.php?id=<?= (int)$file['id'] ?>"><?= h($file['original_name']) ?></a><?php endforeach; ?></div><form method="post" class="chat-form"><input type="hidden" name="csrf" value="<?= h(csrf_token()) ?>"><input type="hidden" name="submission_id" value="<?= (int)$row['id'] ?>"><input type="number" name="score" min="0" max="<?= h((string)$a['max_score']) ?>" step="0.01" value="<?= h((string)($row['score']??'')) ?>" placeholder="Nota"><input name="feedback" maxlength="5000" value="<?= h((string)$row['feedback']) ?>" placeholder="Retroalimentación"><select name="submission_status"><option value="graded">Calificar</option><option value="returned">Devolver</option></select><button class="mini-button" name="action" value="submission_grade">Guardar</button></form></article><?php endforeach; ?></section><?php endforeach; ?>
<?php else: ?><section class="welcome"><div><p class="eyebrow">ESTUDIANTE</p><h1>Mis tareas</h1><p class="muted">Consulta instrucciones, guarda borradores y revisa la retroalimentación.</p></div></section><?php $q=$pdo->prepare("SELECT DISTINCT a.*,s.id submission_id,s.status submission_status,s.response_text,s.score,s.feedback FROM assignments a JOIN assignment_targets t ON t.assignment_id=a.id LEFT JOIN assignment_submissions s ON s.assignment_id=a.id AND s.student_id=? WHERE a.status IN ('published','closed') AND (t.student_id=? OR (t.grade_level=? AND t.group_id IS NULL) OR (t.group_id IS NOT NULL AND EXISTS(SELECT 1 FROM group_students gs WHERE gs.group_id=t.group_id AND gs.student_id=?))) ORDER BY a.due_at IS NULL,a.due_at");$q->execute([$uid,$uid,$me['grade_level']??null,$uid]);foreach($q->fetchAll() as $a): ?><section class="panel"><h2><?= h($a['title']) ?> <span class="soft-tag"><?= h((string)($a['submission_status']??'pendiente')) ?></span></h2><p><?= nl2br(h($a['instructions'])) ?></p><p class="muted">Vence: <?= $a['due_at']?h(date('d/m/Y H:i',strtotime($a['due_at']))):'Sin fecha límite' ?> · Nota máxima <?= h((string)$a['max_score']) ?></p><?php $f=$pdo->prepare('SELECT id,original_name FROM assignment_files WHERE assignment_id=? AND submission_id IS NULL');$f->execute([$a['id']]);foreach($f->fetchAll() as $file): ?><a href="descargar-adjunto.php?id=<?= (int)$file['id'] ?>"><?= h($file['original_name']) ?></a><?php endforeach; ?><?php if($a['score']!==null): ?><div class="notice">Nota: <?= h((string)$a['score']) ?> · <?= h((string)$a['feedback']) ?></div><?php endif; ?><?php if(!$a['submission_status']||$a['submission_status']==='draft'||($a['submission_status']==='returned'&&$a['allow_resubmission'])): ?><form method="post" enctype="multipart/form-data" class="stack"><input type="hidden" name="csrf" value="<?= h(csrf_token()) ?>"><input type="hidden" name="assignment_id" value="<?= (int)$a['id'] ?>"><label>Respuesta<textarea name="response_text" maxlength="20000"><?= h((string)$a['response_text']) ?></textarea></label><label>Adjuntar archivo (máx. 5 MB)<input type="file" name="submission_file" accept=".pdf,.png,.jpg,.jpeg,.txt,.docx"></label><button class="mini-button" name="action" value="assignment_draft">Guardar borrador</button><button class="button primary" name="action" value="assignment_submit">Entregar tarea</button></form><?php endif; ?><?php $f=$pdo->prepare('SELECT id,original_name FROM assignment_files WHERE submission_id=?');$f->execute([$a['submission_id']]);foreach($f->fetchAll() as $file): ?><a href="descargar-adjunto.php?id=<?= (int)$file['id'] ?>"><?= h($file['original_name']) ?></a><?php endforeach; ?></section><?php endforeach; ?><?php endif; ?></main></body></html>
